using System;using System.IO;using System.Linq;using System.Reflection;using UnityEditor;using UnityEngine;using UnityEngine.Rendering.Universal;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;using Staff.Subway;
namespace Staff.Rendering.Editor {
[InitializeOnLoad] public static class WorldEntryReview {
 const string W="Library/WorldEntry/";static WorldEntryReview(){EditorApplication.update+=Poll;}
 static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isUpdating||!File.Exists(W+"review.request"))return;File.Delete(W+"review.request");try{Run();}catch(Exception e){File.WriteAllText(W+"error.txt",e.ToString());}}
 static void Run(){Directory.CreateDirectory(W);if(File.Exists(W+"error.txt"))File.Delete(W+"error.txt");var scene=Application.isPlaying?SceneManager.CreateScene("Temporary world entry review"):EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Additive);var root=new GameObject("Review geometry");SceneManager.MoveGameObjectToScene(root,scene);var camGo=new GameObject("Review camera");SceneManager.MoveGameObjectToScene(camGo,scene);var cam=camGo.AddComponent<Camera>();cam.enabled=false;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(.13f,.19f,.25f);cam.cullingMask=1<<31;cam.nearClipPlane=.1f;cam.farClipPlane=100;cam.transform.position=new Vector3(18,14,-22);cam.transform.LookAt(new Vector3(0,2,4));cam.GetUniversalAdditionalCameraData().SetRenderer(0);
 var mode=camGo.AddComponent<AbstractEnvironment>();mode.environmentRoot=root.transform;mode.surfaceShader=Shader.Find("STAFF/Environment/Abstract Surface");mode.geometryShader=Shader.Find("Hidden/STAFF/Abstract Geometry");mode.edgeShader=Shader.Find("Hidden/STAFF/Abstract Edges");var material=new Material(Shader.Find("Universal Render Pipeline/Unlit"));material.SetColor("_BaseColor",new Color(.32f,.45f,.55f));
 try{Cube(root.transform,material,new Vector3(0,-.25f,0),new Vector3(40,.5f,40));Cube(root.transform,material,new Vector3(-8,4,6),new Vector3(5,8,5));Cube(root.transform,material,new Vector3(7,6,9),new Vector3(5,12,5));Cube(root.transform,material,new Vector3(0,4,16),new Vector3(25,8,1));
 mode.BeginEntry(Vector3.zero);var start=typeof(AbstractEnvironment).GetField("entryStart",BindingFlags.Instance|BindingFlags.NonPublic);var original=root.GetComponentInChildren<Renderer>().sharedMaterial;
 foreach(float t in new[]{0f,.18f,.32f,.48f,.65f,.85f,.999f}){start.SetValue(mode,Time.unscaledTime-mode.entryDuration*t);Capture(cam,"step-"+Mathf.RoundToInt(t*100));if(root.GetComponentInChildren<Renderer>().sharedMaterial!=original)throw new Exception("Original materials changed during entry");}
 // Same world front from another viewpoint: the grid must remain on the mesh.
 start.SetValue(mode,Time.unscaledTime-mode.entryDuration*.48f);cam.transform.position=new Vector3(-20,10,-15);cam.transform.LookAt(new Vector3(0,2,4));Capture(cam,"orbit");
 mode.SetMode(AbstractEnvironment.EnvironmentMode.Abstract);Capture(cam,"complete");
 mode.BeginTransition(AbstractEnvironment.EnvironmentMode.Imaginary,Vector3.zero);foreach(float t in new[]{0f,.32f,.65f,.999f}){start.SetValue(mode,Time.unscaledTime-mode.entryDuration*t);Capture(cam,"imaginary-"+Mathf.RoundToInt(t*100));}
 mode.SetMode(AbstractEnvironment.EnvironmentMode.Imaginary);mode.BeginTransition(AbstractEnvironment.EnvironmentMode.Real,Vector3.zero);foreach(float t in new[]{0f,.32f,.65f,.999f}){start.SetValue(mode,Time.unscaledTime-mode.entryDuration*t);Capture(cam,"real-"+Mathf.RoundToInt(t*100));}
 mode.SetMode(AbstractEnvironment.EnvironmentMode.Real);if(root.GetComponentInChildren<Renderer>().sharedMaterial!=original)throw new Exception("Real materials not restored");
 foreach(var shader in new[]{mode.surfaceShader,mode.edgeShader,Shader.Find("Hidden/STAFF/URP Geometry")})if(ShaderUtil.ShaderHasError(shader))throw new Exception("Shader error: "+shader.name);
 File.WriteAllText(W+"result.txt","PASS live Real materials during entry; horizontal mesh grid + delayed fill; orbit; completed Abstract; Abstract to Imaginary; Imaginary to Real; restore Real; shader compilation\n");
 }finally{mode.SetMode(AbstractEnvironment.EnvironmentMode.Real);UnityEngine.Object.DestroyImmediate(camGo);UnityEngine.Object.DestroyImmediate(root);UnityEngine.Object.DestroyImmediate(material);if(Application.isPlaying)SceneManager.UnloadSceneAsync(scene);else EditorSceneManager.CloseScene(scene,true);}}
 static void Cube(Transform root,Material material,Vector3 p,Vector3 scale){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.layer=31;g.transform.SetParent(root,false);g.transform.localPosition=p;g.transform.localScale=scale;g.GetComponent<Renderer>().sharedMaterial=material;}
 static void Capture(Camera camera,string name){var rt=new RenderTexture(960,540,24,RenderTextureFormat.ARGBHalf);var previous=RenderTexture.active;var target=camera.targetTexture;var image=new Texture2D(960,540,TextureFormat.RGBAFloat,false,true);try{camera.targetTexture=rt;StaffCameraCapture.Render(camera);RenderTexture.active=rt;image.ReadPixels(new Rect(0,0,960,540),0,0);image.Apply();var png=new Texture2D(960,540,TextureFormat.RGB24,false);png.SetPixels(image.GetPixels().Select(c=>c.gamma).ToArray());png.Apply();File.WriteAllBytes(W+name+".png",png.EncodeToPNG());UnityEngine.Object.DestroyImmediate(png);}finally{camera.targetTexture=target;RenderTexture.active=previous;UnityEngine.Object.DestroyImmediate(image);rt.Release();UnityEngine.Object.DestroyImmediate(rt);}}
 }
}
